import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

export default function FraudSection() {
  const [progress, setProgress] = useState(0);
  const [isMobile, setIsMobile] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check, { passive: true });
    return () => window.removeEventListener("resize", check);
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const el = sectionRef.current; if (!el) return;
      const rect = el.getBoundingClientRect();
      const p = clamp(-rect.top / (el.offsetHeight - window.innerHeight), 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  // ── Part 1: Fraud section animations ──
  const titleP  = ease(clamp(progress / 0.12, 0, 1));       // faster: was /0.25
  const chartP  = ease(clamp((progress - 0.08) / 0.18, 0, 1)); // faster: was -0.15/0.40
  const footerP = ease(clamp((progress - 0.22) / 0.10, 0, 1)); // faster: was -0.70/0.20

  // ── Part 2: Question section animations — start after part 1 ──
  const title1P = ease(clamp((progress - 0.32) / 0.10, 0, 1)); // faster: was /0.15
  const cards1P = ease(clamp((progress - 0.38) / 0.12, 0, 1)); // faster: was -0.08/0.20
  const title2P = ease(clamp((progress - 0.52) / 0.10, 0, 1)); // faster: was -0.35/0.15
  const cards2P = ease(clamp((progress - 0.58) / 0.12, 0, 1)); // faster: was -0.42/0.20

  const questions = [
    { img: "/assets/question1.png", text: "Which segments are the most risk-prone?" },
    { img: "/assets/question2.png", text: "Where are the risk hotspots across the country?" },
    { img: "/assets/question3.png", text: "What correlations exist between risk rates and other factors?" },
  ];

  const people = [
    { label: "Truck drivers",     riskRate: "4.75%", meanAge: "30.90", img: "/assets/truck-driver.png" },
    { label: "Dark Store Workers", riskRate: "2.36%", meanAge: "24.34", img: "/assets/store.png" },
    { label: "Delivery Partners",  riskRate: "3.04%", meanAge: "27.94", img: "/assets/delivery.png" },
  ];

  return (
    <div ref={sectionRef} style={{ height: "500vh", position: "relative" }}>
      <div style={{
        position: "sticky",
        top: 0,
        height: "100vh",
        overflow: "hidden",
        background: "black",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        padding: isMobile ? "32px 20px 24px" : "48px 64px 36px",
        overflowY: "auto",
      }}>

        {/* Ellipse decoration */}
        <div style={{ position: "absolute", top: 0, right: -430, zIndex: 0, pointerEvents: "none" }}>
          <img
            src="/assets/Ellipse.png"
            alt=""
            style={{ width: "900px", height: "900px", opacity: 1 }}
          />
        </div>

        {/* ══════════════════════════════════════
            PART 1 — Fraud / Chart
        ══════════════════════════════════════ */}
        <div style={{
          width: "100%",
          maxWidth: 980,
          zIndex: 1,
          opacity: titleP,
          transform: `translateY(${lerp(30, 0, titleP)}px)`,
          textAlign: "center",
          marginBottom: isMobile ? 8 : 16,
        }}>
          <h2 style={{
            fontFamily: "'Inter'",
            fontWeight: 700,
            color: "white",
            margin: 0,
            lineHeight: 1.05,
            fontSize: isMobile ? "42px" : "clamp(60px, 8vw, 105px)",
          }}>
            The Fraud Behind{" "}
            <br className="sm:flex hidden" />
            the Workforce
          </h2>
        </div>

        <p style={{
          color: "white",
          fontSize: isMobile ? "13px" : "clamp(14px,1.1vw,19px)",
          fontWeight: 600,
          margin: isMobile ? "0 0 10px" : "0 0 16px",
          textAlign: "center",
          fontFamily: "'Inter',sans-serif",
          zIndex: 1,
          opacity: titleP,
          transform: `translateY(${lerp(20, 0, titleP)}px)`,
        }}>
          India's gig workforce has grown from
        </p>

        {/* Chart GIF */}
        <div style={{
          width: "100%",
          maxWidth: isMobile ? "100%" : 880,
          opacity: chartP,
          transform: `translateY(${lerp(20, 0, chartP)}px)`,
          zIndex: 1,
        }}>
          <img
            src="/assets/graph.gif"
            alt="Gig workforce growth chart"
            style={{ width: "100%", display: "block", borderRadius: 4 }}
          />
          <div style={{ textAlign: "center", marginTop: 6, marginBottom: 4, opacity: footerP }}>
            <span style={{ color: "rgba(255,255,255,0.38)", fontSize: isMobile ? 11 : 13, fontFamily: "'Inter',sans-serif" }}>
              Source:{" "}
              <a href="https://www.niti.gov.in/sites/default/files/2023-06/Policy_Brief_India%27s_Booming_Gig_and_Platform_Economy_27062022.pdf"
                target="_blank" rel="noreferrer"
                style={{ color: "rgba(255,255,255,0.58)", textDecoration: "underline" }}>
                Niti Ayog
              </a>
              {" "}and{" "}
              <a href="https://www.livemint.com/money/personal-finance/indias-gig-economy-in-2025-growth-formalisation-and-financial-inclusion-explained-11753438649777.html"
                target="_blank" rel="noreferrer"
                style={{ color: "rgba(255,255,255,0.58)", textDecoration: "underline" }}>
                Mint
              </a>
            </span>
          </div>
        </div>

        <p style={{
          color: "white",
          fontSize: isMobile ? "14px" : "clamp(15px,1.3vw,21px)",
          fontFamily: "'Inter',sans-serif",
          textAlign: "center",
          margin: isMobile ? "8px 0 20px" : "4px 0 32px",
          maxWidth: 700,
          zIndex: 1,
          opacity: footerP,
        }}>
          But as the workforce expands, fraud scales alongside it.
        </p>

        {/* ══════════════════════════════════════
            PART 2 — Questions + People
        ══════════════════════════════════════ */}

        {/* Divider */}
        <div style={{
          width: "100%", maxWidth: 1300,
          height: 1, background: "rgba(255,255,255,0.12)",
          marginBottom: isMobile ? 20 : 32,
          opacity: title1P, zIndex: 1,
        }} />

        {/* "This section answers questions like" */}
        <div style={{ width: "100%", maxWidth: 1300, zIndex: 1 }}>
          <h2 style={{
            fontFamily: "'Inter','Helvetica Neue',sans-serif",
            fontWeight: 700, color: "white",
            fontSize: isMobile ? "28px" : "clamp(32px, 4vw, 56px)",
            margin: "0 0 20px", textAlign: "center", lineHeight: 1.08,
            opacity: title1P,
            transform: `translateY(${lerp(40, 0, title1P)}px)`,
          }}>
            This section answers questions like
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
            gap: isMobile ? 16 : 16,
            width: "100%",
            marginBottom: isMobile ? 24 : 32,
          }}>
            {questions.map((q, i) => {
              const cp = ease(clamp((cards1P * 1 - i * 0.15), 0, 1));
              return (
                <div key={i} style={{
                  backgroundImage: "linear-gradient(#1d1d1d,#212121)",
                  border: "1px solid white",
                  borderRadius: 16, padding: "16px 18px",
                  display: "flex", alignItems: "center", gap: 16,
                  minHeight: 90,
                  opacity: cp,
                  transform: `translateY(${lerp(30, 0, cp)}px) scale(${lerp(0.96, 1, cp)})`,
                }}>
                  <div style={{
                    width: 64, height: 64, flexShrink: 0,
                    borderRadius: 12,
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    <img src={q.img} alt="" style={{ width: 120, height: 80, objectFit: "contain" }} />
                  </div>
                  <p style={{
                    color: "white", fontSize: "clamp(12px,1vw,16px)",
                    fontWeight: 500, margin: 0, lineHeight: 1.5,
                    fontFamily: "'Inter',sans-serif",
                  }}>{q.text}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Divider 2 */}
        <div style={{
          width: "100%", maxWidth: 1300,
          height: 1, background: "rgba(255,255,255,0.08)",
          marginBottom: isMobile ? 20 : 28,
          opacity: title2P, zIndex: 1,
        }} />

        {/* People in focus */}
        <div style={{ width: "100%", maxWidth: 1100, zIndex: 1 }}>
          <h2
            className="bg-gradient-to-r from-[#cdcdcd] to-white bg-clip-text text-transparent"
            style={{
              fontFamily: "'Inter','Helvetica Neue',sans-serif",
              fontWeight: 700,
              fontSize: isMobile ? "36px" : "clamp(36px, 5vw, 72px)",
              margin: "0 0 20px",
              textAlign: "center",
              lineHeight: 1.05,
              opacity: title2P,
              transform: `translateY(${lerp(24, 0, title2P)}px)`,
            }}
          >
            People in focus
          </h2>

          <div style={{
            display: "grid",
            gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)",
            gap: isMobile ? 16 : 16,
            width: "100%",
          }}>
            {people.map((p, i) => {
              const cp = ease(clamp((cards2P * 1 - i * 0.15), 0, 1));
              return (
                <div key={i} style={{
                  background: "rgba(255,255,255,0.06)",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: 16,
                  padding: "22px 24px 0",
                  display: "flex", flexDirection: "column",
                  position: "relative", overflow: "hidden",
                  minHeight: 220,
                  opacity: cp,
                  transform: `translateY(${lerp(30, 0, cp)}px)`,
                }}>
                  <div style={{ color: "#CE1010", fontSize: "16px", fontWeight: 600, marginBottom: 10, fontFamily: "'Inter',sans-serif" }}>{p.label}</div>
                  <div style={{ color: "white", fontSize: "clamp(24px,2.5vw,38px)", fontWeight: 700, lineHeight: 1, fontFamily: "'Inter',sans-serif" }}>{p.riskRate}</div>
                  <div style={{ color: "white", fontSize: 15, marginTop: 4, marginBottom: 14 }}>Risk Rate</div>
                  <div style={{ color: "white", fontSize: 15, marginBottom: 6 }}>Mean Age</div>
                  <div style={{ color: "white", fontSize: "clamp(24px,2.5vw,38px)", fontWeight: 700, lineHeight: 1, fontFamily: "'Inter',sans-serif" }}>{p.meanAge}</div>
                  <div style={{ color: "white", fontSize: 15, marginTop: 6, marginBottom: 16 }}>years</div>
                  <img
                    src={p.img}
                    alt={p.label}
                    style={{
                      position: "absolute", bottom: -10, right: -10,
                      width: "34%", maxWidth: 120,
                      objectFit: "contain", objectPosition: "bottom right",
                      transform: "rotate(10deg)", transformOrigin: "bottom right",
                      opacity: 0.88,
                    }}
                  />
                </div>
              );
            })}
          </div>
        </div>

      </div>
    </div>
  );
}
